// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address originEOA, address candidateNewOwner) public {
        vm.assume(originEOA != address(0));
        vm.assume(candidateNewOwner != address(0));

        Forwarder f = new Forwarder();

        vm.deal(originEOA, 1 ether);

        vm.assume(originEOA != address(this));

        bool ok;
        try c.setOwner(originEOA) { ok = true; } catch { ok = false; }
        assertTrue(ok);

        vm.prank(originEOA);
        try f.forwardSetOwner(address(c), candidateNewOwner) { ok = true; } catch { ok = false; }

        assertTrue(c.owner() == originEOA);
    }
}

contract Forwarder {
    function forwardSetOwner(address target, address newOwner) external {
        (bool success, ) = target.call(abi.encodeWithSelector(bytes4(keccak256("setOwner(address)")), newOwner));
        require(success);
    }
}
